INSERT INTO `item_template` SELECT * FROM `tmp_shrink`;
INSERT INTO `tmp_shrink` (`entry`,`class`,`subclass`,`name`,`displayid`,`Quality`,`BuyPrice`,`SellPrice`,`InventoryType`,`ItemLevel`,`shadow_res`,`delay`,`spellid_1`,`spellcooldown_1`,`bonding`,`description`) VALUES
(1205516,15,2,'Billy',1201052,1,0,0,0,1,0,1000,1200703,0,1,'The ducks of Northwind are known for their distinctive call, and Billy is no different!'),
(1200040,15,2,'Crimson Sabercat Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'A spirited companion, its fiery fur captures the essence of youthful adventure in the wilds of Azeroth.'),
(1200041,15,2,'Alliance Lion Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'A pint-sized embodiment of courage and unity, sporting the iconic golden mane of its proud lion lineage.'),
(1200042,15,2,'Spot',5689,1,0,0,0,1,0,1000,1200703,0,1,'A playful feline companion adorned with distinctive spots, bringing a touch of the wild to your adventures.'),
(1200043,15,2,'Twilight Paws',5689,1,0,0,0,1,0,1000,1200703,0,1,'A tiny bundle of darkness with a coat of deep, enchanting blue fur, this cute companion brings a touch of mystical charm to your adventures.'),
(1200044,15,2,'Black Panther Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'A tiny shadow prowler, its velvety fur and curious eyes add an adorable touch to your daring escapades.'),
(1200045,15,2,'Tawny',5689,1,0,0,0,1,0,1000,1200703,0,1,'With its soft, tawny fur and playful antics, this adorable cub is a heartwarming companion for your journey through Azeroth.'),
(1200046,15,2,'Nightsaber Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'Elune made nightsabers silver and black so they could meld into the shadows on a moonlit night.'),
(1200047,15,2,'Snow Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'The thick snow near Dun Morogh acts as camouflage for snow cubs learning to hunt.'),
(1200048,15,2,'Stangletorn Tiger Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'This lively and affectionate cub boasts unique stripes, a miniature symbol of the wild beauty found in Stangletorn Vale.'),
(1200049,15,2,'Frostsaber Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'A charming companion with snowy fur adorned by enchanting stripes, bringing the wintry beauty of Azeroth to your side.'),
(1200050,15,2,'Cheetah Cub',5689,1,0,0,0,1,0,1000,1200703,0,1,'These playful feline cubs practice their hunting skills by stalking each other through the Barrens.'),
(1200051,15,2,'Chestnut',6417,1,0,0,0,1,0,1000,1200703,0,1,'With a bushy tail that rivals the fluffiest of pillows, this squirrel is the epitome of woodland charm, spreading happiness wherever it goes.'),
(1206661,15,2,'Webwood Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'A nimble forest crawler, weaving small webs among the leaves to catch morning dew.'),
(1206662,15,2,'Wildthorn Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'Silent and watchful, this spiderling moves carefully through the thorns, ever curious.'),
(1206663,15,2,'Lava Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'Born of flame and stone, its glowing legs light the darkest caves with a gentle warmth.'),
(1206664,15,2,'Tarantula Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'Bright and quick, it darts through sunlit groves, weaving webs as fine as silk.'),
(1206665,15,2,'Timberweb Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'This shy recluse spins intricate webs among fallen timber, blending with the forest floor.'),
(1206666,15,2,'Mistbark Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'This little spiderling wishes to weave its own web across the forests of Balor one day.'),
(1206667,15,2,'Skitterweb Hatchling',7345,2,0,0,0,1,0,0,1200703,0,1,'Dormant arcane energies cause the harmless kitchen spiders to grow to monstrous sizes.'),
(1206668,15,2,'Black Widow Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'They may not look like much, but their bite leaves a nasty mark. Luckily their poison is still weak.'),
(1206669,15,2,'Night Web Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'The Night Web spiders adapted and learned how to survive in the cursed stretches of the Tirisfal Glades.'),
(1206670,15,2,'Cavernweb Hatchling',7345,2,0,0,0,1,0,0,1200703,0,1,'Native to the mines beneath Grim Batol, this hatchling escaped the dark magic of the Dragonmaw sorcerers.'),
(1206671,15,2,'Razzashi Hatchling',7345,2,0,0,0,1,0,0,1200703,0,1,'Blessed by Shadra herself, this brood is known for their especially potent venom.'),
(1206672,15,2,'Araxxna\'s Hatchling',7345,2,0,0,0,1,0,0,1200703,0,1,'Broodmother Araxxna gave birth to many eight-legged horrors - and this eight-legged sweetie.'),
(1206673,15,2,'Maexxna\'s Hatchling',7345,2,0,0,0,1,0,0,1200703,0,1,'One of the few rare hatchlings of Maexxna, this little one feasts on corpses just like its mother.'),
(1206674,15,2,'Darkmist Hatchling',7345,1,0,0,0,1,0,0,1200703,0,1,'The infamous Darkmist netting is strong enough to web even an ogre. This one, however, can at most catch a rat.'),
(1206675,15,2,'Magus Alfred Wartbeard',7913,1,0,0,0,1,0,0,1200703,0,1,'One moment, I was reading this ancient scroll... the next? Flies. So many flies.'),
(1206676,15,2,'Son of Mergothid',1504,1,0,0,0,1,0,0,1200703,0,1,'Like father, like son.'),
(1206677,15,2,'Swamp Crocolisk Hatchling',6658,1,0,0,0,1,0,0,1200703,0,1,'As hungry as the big ones.'),
(1206678,15,2,'Marsh Crocolisk Hatchling',6658,1,0,0,0,1,0,0,1200703,0,1,'As hungry as the big ones.'),
(1206679,15,2,'Dust Crocolisk Hatchling',6658,1,0,0,0,1,0,0,1200703,0,1,'As hungry as the big ones.'),
(1206680,15,2,'Baby Moonwhisper Elekk',7294,1,8000000,2000000,0,1,0,0,1200703,0,1,'Young elekks are a rare sight these days, yet some remain in the forgotten lands of Moonwhisper Coast.'),
(1206681,15,2,'Baby Ashenvale Elekk',7294,1,0,0,0,1,0,0,1200703,0,1,'Young elekks are a rare sight these days, yet some remain in the enchanted lands of Ashenvale.'),
(1206682,15,2,'Baby Azshara Elekk',7294,1,0,0,0,1,0,0,1200703,0,1,'Young elekks are a rare sight these days, yet some remain in the haunted lands of Azshara.'),
(1206683,15,2,'Hawkstrider Hatchling',18047,1,0,0,0,1,0,0,1200703,0,1,'Miraculously saved from Quel\'Thalas.'),
(1206684,15,2,'Tamed Skunk',6691,1,0,0,0,1,0,0,1200703,0,1,'Stinks.'),
(1206685,15,2,'Wolpertinger',28858,1,0,0,0,1,0,0,1200703,0,1,'Not even the wisest druids know what a Wolpentinger is. It\'s best not to dwell on this question.'),
(1206686,15,2,'Portable Zeppelin Prototype',8928,1,0,0,0,1,0,0,1200703,0,1,'Property of DLU.'),
(1206693,15,2,'Potato Fairy',31804,1,0,0,0,1,0,0,1200703,0,1,'The rotund body of this amphibian had you fooled for just a second. It was no yam after all!'),
(1206694,15,2,'Berry Squirrel',20770,1,0,0,0,1,0,0,1200703,0,1,'With a mouth full of berries, this critter got caught feasting on your plentiful harvest.'),
(1206695,15,2,'Pumpkin Marmot',15798,1,0,0,0,1,0,0,1200703,0,1,'A bite strong enough to shred the thick pumpkin shell. Terrifying on its own.'),
(1206696,15,2,'Sand Hare',6682,1,0,0,0,1,0,0,1200703,0,1,'Its brown fur helps it camouflage seemlessly with the sandy ground.'),
(1206697,15,2,'Verdant Melon Muncher',36474,1,0,0,0,1,0,0,1200703,0,1,'This merciless melon demolisher is a menace for all aspiring gardeners.'),
(1206698,15,2,'Wild Autumn Owl',7202,1,0,0,0,1,0,0,1200703,0,1,'These grapes must pack a punch, if this little owl had feasted on them so viciously.'),
(1206699,15,2,'Living Mushroom',15853,1,0,0,0,1,0,0,1200703,0,1,'This mushroom is moving on its own! Just what are they putting in that Spring Water…?'),
(1206704,15,2,'Wood Constrictor',11889,1,0,0,0,1,0,0,1200703,0,1,'You almost mistook this serpent for a twig! Luckily your keen eye caught the difference before your axe could.'),
(1206705,15,2,'Yellow Wasp',8284,1,0,0,0,1,0,0,1200703,0,1,'The steady buzzing of this insect could drive a short-tempered to insanity.'),
(1206706,15,2,'Dung Beetle',8923,1,0,0,0,1,0,0,1200703,0,1,'Comes with bite sized candy. Experts advise against eating them.'),
(1206707,15,2,'Reclusive Spider',7368,1,0,0,0,1,0,0,1200703,0,1,'Just a simple touch and it scurries back into your pocket.'),
(1206708,15,2,'Darkfeather Owl',19529,1,0,0,0,1,0,0,1200703,0,1,'Curious and chatty, at night and at day. You wonder how it survived for so long on its own.'),
(1206709,15,2,'Shadewing Bat',6691,1,0,0,0,1,0,0,1200703,0,1,'This bat has no visible eyes, yet can maneuver effortlessly through the air.'),
(1206710,15,2,'Tropical Monkey',17881,1,0,0,0,1,0,0,1200703,0,1,'Simian real estate is scarce in today\'s times, especially with people chopping trees left and right. You wouldn\'t leave this little fellow all alone, would you?'),
(1206711,15,2,'Vibrant Parrot',19570,1,0,0,0,1,0,0,1200703,0,1,'It is well known that the buccaneers of the South Seas keep parrots as their companions, but not many know that there are educated trainers preparing them for long days at sea.'),
(1206712,15,2,'Sludge Ooze',1507,1,0,0,0,1,0,0,1200703,0,1,'A sluggish gelatinous wanderer, feeding on rot and leaving a glistening trail of decay behind.'),
(1206713,15,2,'Starsilk Moth',57527,1,0,0,0,1,0,0,1200703,0,1,'The silk of this moth glitters in the moonlight like a curtain of endless stars.'),
(1200504,15,2,'Bone Golem',13806,1,0,0,0,1,0,1000,1200703,0,1,'Bone golems are deadly undead constructs made entirely of bones and fueled by ichor of Undeath.'),
(1200505,15,2,'Blitzen',8119,1,0,0,0,1,0,1000,1200703,0,1,'Happy Winter Veil!'),
(1200510,15,2,'Moonkin Hatchling',18050,1,0,0,0,1,0,1000,1200703,0,1,'Moonkins are blessed by Elune and spread nature\'s grace wherever they travel. The festive fowls are always in the mood for a dance.'),
(1200544,15,2,'Black Piglet',7287,1,0,0,0,1,0,1000,1200703,0,1,'An easy-going traveling companion.'),
(1200567,15,2,'Cottontail Rabbit',7913,1,10000,0,0,1,0,1000,1200703,0,1,'Mountain cottontails can leap up a steep incline with speed you would not believe.'),
(1200569,15,2,'Azure Whelpling',31434,1,0,0,0,1,0,1000,1200703,0,1,'Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic.'),
(1200570,15,2,'Kirin Tor Familiar',20614,1,0,0,0,1,0,1000,1200703,0,1,'Who knew he was so into books?'),
(1200571,15,2,'Frostwolf Ghostpup',31475,1,0,0,0,1,0,1000,1200703,0,1,'The little wolf told to stay. Watching, waiting, for vacant prey. Too proud to leave, she slipped away. Unburdened now, forever free to play.'),
(1200679,15,2,'Darkmoon Tonk',4233,1,0,0,0,1,0,1000,1200703,0,1,'A favorite of children across Azeroth, this tough little toy can withstand even the most aggressive imagination.'),
(1200681,15,2,'Egg of Turtlhu',18050,1,0,0,0,1,0,1000,1200703,1,3,'This poor turtle got a bit corrupted, but his heart is still lovely.'),
(1200699,0,0,'Cheap Goblin\'s Oil',21794,1,4500,0,0,0,0,1000,12244,0,1,'Smells horrible.'),
(1200700,0,0,'Wooden Club',2618,1,0,0,0,0,0,1000,12244,0,1,'A simple stick made of wood.'),
(1201060,12,0,'Teresa\'s Copper Coin',6244,1,0,0,0,10,0,0,1200849,0,4,'I\'m not very lucky. Throw this coin in a fountain for me?'),
(1201250,4,0,'Blackrock\'s Lord Shirt',27943,1,0,0,4,1,1,0,1200693,0,1,'Who\'s the Lord now!?'),
(1201251,15,2,'Tirisfal Bat',23725,1,0,0,0,1,0,0,1200703,0,1,'This foreboding creature stalks the night skies of the Eastern Plaguelands, feeding on carrion.'),
(1208163,15,2,'Caretaker Brambleclaw',28952,1,0,0,0,1,0,1000,1200703,0,1,'Summon Caretaker Brambleclaw, the furbolg stable master, to tend to your mounts with his expert care and deep bond with all creatures.'),
(1208164,15,2,'Squire Boltfling',1200922,1,0,0,0,1,0,1000,1200703,0,1,'Summon Squire Boltfling, the knight\'s trusty squire, to provide you with top-quality ammunition and keep you armed for any battle.'),
(1208170,15,2,'Black Bear Cub',28952,1,0,0,0,1,0,0,1200703,0,6,'A fluffy ball of chaos and claws, the Black Bear Cub is here to eat your snacks, steal your heart, and maybe, eventually, be useful in battle.'),
(1208586,15,2,'Pumpkin',6668,1,6000,0,0,1,0,0,1200703,0,1,'This playful pup with a warm, orange coat is always ready for adventure, bringing a touch of cheer to your journey.'),
(1208587,15,2,'Biscuit',6668,1,6000,0,0,1,0,0,1200703,0,1,'With its noble black and white coat, this corgi exudes both grace and bravery, a perfect ally for any adventurer.'),
(1203552,15,2,'Lovely Pink Fox',1200115,1,0,0,0,1,0,0,1200703,0,1,'A shy creature, the pink fox will only make its presence known to those that have befriended it.'),
(1204163,15,2,'Cheeky Monkey',20629,1,0,0,0,1,0,0,1200703,0,1,'With their mischievous nature and cute antics, these baby monkeys are the perfect companions to brighten up your adventures in Azeroth.'),
(1204167,15,2,'Midnight',20629,2,4000,1000,0,1,0,0,1200703,0,3,'Ride with the moon (and this furry, whiskered witch) in the dead of night!'),
(1208600,15,2,'Zephyr',23358,1,0,0,0,1,0,1000,1200703,0,1,'A swift and gentle gazelle, Zephyr dances through the Barrens with the grace of the wind, always by your side on every adventure.'),
